schema:
CREATE TABLE stores (store_id INTEGER PRIMARY KEY AUTOINCREMENT, store_name TEXT NOT NULL, region TEXT NOT NULL, monthly_goal INT NOT NULL);
CREATE TABLE employees (employee_id INTEGER PRIMARY KEY AUTOINCREMENT, employee_name TEXT NOT NULL, store_id INT NOT NULL REFERENCES stores(store_id), hire_date DATE NOT NULL);
CREATE TABLE customers (customer_id INTEGER PRIMARY KEY AUTOINCREMENT, age_band TEXT NOT NULL, signup_date DATE NOT NULL);
CREATE TABLE plans (plan_id INTEGER PRIMARY KEY AUTOINCREMENT, plan_name TEXT NOT NULL, monthly_revenue NUMERIC NOT NULL, is_magenta BOOLEAN NOT NULL);
CREATE TABLE sales (sale_id INTEGER PRIMARY KEY AUTOINCREMENT, sale_date DATE NOT NULL, store_id INT NOT NULL REFERENCES stores(store_id), employee_id INT NOT NULL REFERENCES employees(employee_id), customer_id INT NOT NULL REFERENCES customers(customer_id), plan_id INT NOT NULL REFERENCES plans(plan_id), device_price NUMERIC NOT NULL, voice_lines INT NOT NULL DEFAULT 1, tablet_lines INT NOT NULL DEFAULT 0, home_internet BOOLEAN NOT NULL DEFAULT 0, accessory_attach BOOLEAN NOT NULL DEFAULT 0, accessory_revenue NUMERIC NOT NULL DEFAULT 0, insurance_attach BOOLEAN NOT NULL DEFAULT 0);
CREATE INDEX idx_sales_date ON sales(sale_date);
CREATE INDEX idx_sales_store ON sales(store_id);
CREATE INDEX idx_sales_employee ON sales(employee_id);
